window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ffd5fc55fa1c3353"]={"versions": [{"id": "FIG-ffd5fc55fa1c3353", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokolllayout-Diagramm des Header-Typs <code>HTYP2</code> im Kontext des AUTOSAR Diagnostic Log and Trace (DLT) Protokolls (<code>AUTOSAR_PRS_LogAndTraceProtocol</code>). Das 32-Bit-Feld (4 Bytes, Byte 0 bis Byte 3, jeweils Bits 7 bis 0) steuert die Struktur und das Vorhandensein optionaler Header-Felder in einer DLT-Nachricht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die 4 Bytes des Feldes <code>HTYP2</code> definieren folgende Steuerbits und Bitgruppen:</p>\n<ul class=\"fig-list\"><li><strong>Byte 0</strong>:\n<ul class=\"fig-list\"><li><code>VERS</code> (Bits 7–5, 3 Bits): DLT-Protokollversion.\n</li><li><code>WSID</code> (Bit 4, 1 Bit): With Session ID (Kennzeichnet das Vorhandensein der Session-ID).\n</li><li><code>WACID</code> (Bit 3, 1 Bit): With Application ID / Context ID (Kennzeichnet das Vorhandensein von Application- und Context-ID).\n</li><li><code>WEID</code> (Bit 2, 1 Bit): With ECU ID (Kennzeichnet das Vorhandensein der ECU-ID).\n</li><li><code>CNTI</code> (Bits 1–0, 2 Bits): Content Info (Kennzeichnung des Nachrichteninhalts / Payload-Typs).\n</li></ul>\n</li><li><strong>Byte 1</strong>:\n<ul class=\"fig-list\"><li>Bits 7–3: <code>reserved</code> (reserviert).\n</li><li><code>WPVL</code> (Bit 2, 1 Bit): With Privacy Level (Kennzeichnet das Vorhandensein des Privacy-Level-Felds).\n</li><li><code>WTGS</code> (Bit 1, 1 Bit): With Trace Status (Kennzeichnet das Vorhandensein des Trace-Status-Felds).\n</li><li><code>WSFLN</code> (Bit 0, 1 Bit): With Source File &amp; Line Number (Kennzeichnet das Vorhandensein von Dateiname und Zeilennummer).\n</li></ul>\n</li><li><strong>Byte 2</strong>: Bits 7–0 sind als <code>reserved</code> deklariert.\n</li><li><strong>Byte 3</strong>: Bits 7–0 sind als <code>reserved</code> deklariert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bit- und Byte-Kodierungsschema ohne dynamische Zustandsübergänge oder Sequenzabläufe. Die Bits steuern serialisierungsseitig das Einbetten nachgelagerter Standard- und erweiterter Header-Elemente sowie deserialisierungsseitig das Parsen der variablen DLT-Nachrichtenstruktur.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich gemäß Anforderung <code>[PRS_Dlt_01009]</code> für Parser und Serialisierer des DLT-Protokolls:</p>\n<ul class=\"fig-list\"><li>Die Bit-Offsets und Feldbreiten müssen bitgenau ausgewertet und serialisiert werden.\n</li><li>Alle als <code>reserved</code> markierten Bits in Byte 1 (Bits 7–3) sowie Byte 2 und 3 müssen gemäß Spezifikation standardmäßig auf <code>0</code> gesetzt und von Empfängern fehlertolerant ignoriert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-053cd2687f464ac3", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bitfeld- und Protokolllayout-Diagramm des Header-Typs <code>HTYP2</code> im Kontext des AUTOSAR Diagnostic Log and Trace (DLT) Protokolls (<code>AUTOSAR_PRS_LogAndTraceProtocol</code>). Das 32-Bit-Feld (4 Bytes, Byte 0 bis Byte 3, jeweils Bits 7 bis 0) steuert die Struktur und das Vorhandensein optionaler Header-Felder in einer DLT-Nachricht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die 4 Bytes des Feldes <code>HTYP2</code> definieren folgende Steuerbits und Bitgruppen:</p>\n<ul class=\"fig-list\"><li><strong>Byte 0</strong>:\n<ul class=\"fig-list\"><li><code>VERS</code> (Bits 7–5, 3 Bits): DLT-Protokollversion.\n</li><li><code>WSID</code> (Bit 4, 1 Bit): With Session ID (Kennzeichnet das Vorhandensein der Session-ID).\n</li><li><code>WACID</code> (Bit 3, 1 Bit): With Application ID / Context ID (Kennzeichnet das Vorhandensein von Application- und Context-ID).\n</li><li><code>WEID</code> (Bit 2, 1 Bit): With ECU ID (Kennzeichnet das Vorhandensein der ECU-ID).\n</li><li><code>CNTI</code> (Bits 1–0, 2 Bits): Content Info (Kennzeichnung des Nachrichteninhalts / Payload-Typs).\n</li></ul>\n</li><li><strong>Byte 1</strong>:\n<ul class=\"fig-list\"><li>Bits 7–4: <code>reserved</code> (reserviert).\n</li><li><code>WSGM</code> (Bit 3, 1 Bit): Steuerflag (With Segmented Message / Segmentierung).\n</li><li><code>WPVL</code> (Bit 2, 1 Bit): With Privacy Level (Kennzeichnet das Vorhandensein des Privacy-Level-Felds).\n</li><li><code>WTGS</code> (Bit 1, 1 Bit): With Trace Status (Kennzeichnet das Vorhandensein des Trace-Status-Felds).\n</li><li><code>WSFLN</code> (Bit 0, 1 Bit): With Source File &amp; Line Number (Kennzeichnet das Vorhandensein von Dateiname und Zeilennummer).\n</li></ul>\n</li><li><strong>Byte 2</strong>: Bits 7–0 sind als <code>reserved</code> deklariert.\n</li><li><strong>Byte 3</strong>: Bits 7–0 sind als <code>reserved</code> deklariert.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Bit- und Byte-Kodierungsschema ohne dynamische Zustandsübergänge oder Sequenzabläufe. Die Bits steuern serialisierungsseitig das Einbetten nachgelagerter Standard- und erweiterter Header-Elemente sowie deserialisierungsseitig das Parsen der variablen DLT-Nachrichtenstruktur.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindlich gemäß Anforderung <code>[PRS_Dlt_01009]</code> für Parser und Serialisierer des DLT-Protokolls:</p>\n<ul class=\"fig-list\"><li>Die Bit-Offsets und Feldbreiten müssen bitgenau ausgewertet und serialisiert werden.\n</li><li>Das Bit <code>WSGM</code> an Byte 1, Bit 3 bestimmt das Vorhandensein des zugehörigen Segmentierungsfelds bzw. -zustands.\n</li><li>Alle verbleibenden als <code>reserved</code> markierten Bits in Byte 1 (Bits 7–4) sowie Byte 2 und 3 müssen standardmäßig auf <code>0</code> gesetzt und von Empfängern fehlertolerant ignoriert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-ffd5fc55fa1c3353", "to": "FIG-053cd2687f464ac3", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Header Type (HTYP2), Byte 1, Bit 3</strong>: Das bisher als <code>reserved</code> geführte Bit wird als Steuerbit <code>WSGM</code> definiert.\n</li></ul>"}]};
